UPDATE dbo.[NFD_Trainees] SET [ProfileImageUrl] = N'https://cdn.nafadh.test/profiles/trainee/' + CAST([TraineeId] AS NVARCHAR(10)) + N'.jpg' WHERE [ProfileImageUrl] IS NULL;
